insert into sectors(slug,name,summary) values
('financials','Financials','Banks, NBFCs, insurance and capital markets'),('infrastructure','Infrastructure','Roads, rail, ports, construction and logistics'),('energy','Energy','Power, renewables, oil, gas and grid'),('technology','Technology','IT services, electronics, SaaS and digital economy'),('manufacturing','Manufacturing','Capital goods, chemicals, textiles and industrials'),('defence','Defence','Platforms, electronics, shipbuilding and aerospace'),('healthcare','Healthcare','Pharma, hospitals, diagnostics and devices'),('agriculture','Agriculture','Inputs, food processing, rural economy and logistics') on conflict(slug) do update set name=excluded.name,summary=excluded.summary;
insert into industries(sector_id,slug,name) select s.id,v.slug,v.name from sectors s join (values
('financials','banks','Banks'),('financials','nbfc','NBFC'),('financials','insurance','Insurance'),('financials','capital-markets','Capital Markets'),('infrastructure','roads','Roads'),('infrastructure','railways','Railways'),('infrastructure','ports','Ports'),('infrastructure','logistics','Logistics'),('energy','power','Power'),('energy','renewables','Renewables'),('energy','oil-gas','Oil & Gas'),('energy','storage','Storage'),('technology','it-services','IT Services'),('technology','electronics','Electronics'),('technology','saas','SaaS'),('technology','digital-platforms','Digital Platforms'),('manufacturing','capital-goods','Capital Goods'),('manufacturing','chemicals','Chemicals'),('manufacturing','textiles','Textiles'),('manufacturing','industrials','Industrials'),('defence','aerospace','Aerospace'),('defence','electronics','Electronics'),('defence','shipbuilding','Shipbuilding'),('defence','land-systems','Land Systems'),('healthcare','pharma','Pharma'),('healthcare','hospitals','Hospitals'),('healthcare','diagnostics','Diagnostics'),('healthcare','devices','Devices'),('agriculture','inputs','Inputs'),('agriculture','food-processing','Food Processing'),('agriculture','agri-logistics','Agri Logistics'),('agriculture','rural-finance','Rural Finance')) v(sector_slug,slug,name) on s.slug=v.sector_slug on conflict(sector_id,slug) do update set name=excluded.name;
